-- aar/w3/aar_row_650_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 650 (the Wall manual's AAR section requires the parts WHY THE ORACLE LOST and BUGS) and its ask_aar_builders row.
-- Every value is from W3's own write call (the_wall_manual v21, log row 18, audit 42271), Wall 12065, 12080, 12083, 12085, 12093, 12096, 12104 and 12106, the two cards in W3's thread, and md5sum by W3 of the files named.
-- The operator's words of 08:18 and 08:33 CST are as relayed to W3 (Wall 12065 and the coordinator); his words of 08:43 CST were written in W3's thread.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (650, '0', $t$ASK 650: the Wall manual requires every run AAR to state why the Debate Oracle lost, then the bugs$t$,
  $t$The Wall manual's AAR section (7.4) did not ask why the Debate Oracle lost and had no part for bugs as an objective. Change, in section 7.4 only: two parts are added between RUN and OBJECTIVE. WHY THE ORACLE LOST states the primary objective of every run (to determine why the Debate Oracle is losing rounds) and requires, for each round or link the Debate Oracle lost, what the judges held against it in their own lines, the round text, and the cause named as the Oracle's argument, a judge's misreading, or the engine; the rounds of both sides and every seated judgment are read whole first; NONE LOST and NO VERDICT (with NOT COUNTED) forms; the causes are carried forward as the stated primary objective of the next run, whose report states for each whether it recurred. BUGS states the second objective and requires each bug the run showed with the record that shows it and who found it, or NONE FOUND, each also carried under NEW DEFECTS or DEFECTS NOT RESOLVED. Expected effect: every run AAR from now opens, after its RUN line, with why the Oracle lost and then the bugs.$t$,
  'in part',
  $t$Written by W3 at 08:53 CST 2026-11-25 on the operator's press "Write it" (08:52 CST) on W3's card: the_wall_manual version 20 (3fddfa284698997506798a0d4142ab18, 12,507 characters) to version 21 (370fff76f0e2c05cf19e27bbb6feb452, 13,678), one literal replacement, the old text found once, with its the_wall_manual_log row 18 and audit 42271 (Wall 12104). W1 readback PASS (Wall 12106): version 21 is the latest version, 13,678 characters, md5 370fff76f0e2c05cf19e27bbb6feb452, and in SQL it equals version 20 with the graded draft 3 pair applied. W1 did not check log row 18 or audit 42271. Nothing was deleted; 1,171 characters were added. IN PART: the rule is written, and the findings on run 42528 (Wall 12081, corrected by 12094 and by W1's 12099) were written before it, but no run has been made since, so no AAR has yet been drafted under the written rule, and no next-run report has yet stated whether a carried cause recurred. Three drafts: draft 1 answered the operator's words of 08:18 and 08:33 CST; draft 2 applied W1's N1 (a run with no verdict) and went to the operator on a card; draft 3 gave the second objective its own part, in his word BUGS. W3's MISTAKES, reported to the operator at the time: drafts 1 and 2 wrote "errors in the system are the second objective" as a clause, replacing his word BUGS and giving the second objective no part; he asked at 08:43 CST "where is the second objective i mentioned", and the draft 2 card was withdrawn unwritten. W1's advisory notes N2 (a pointer in OBJECTIVE) and N3 (section 7.3 seat reviews open with the same part) were not taken: each changes a part his request does not name. Open: the next run's AAR.$t$,
  '12065, 12080, 12083, 12085, 12093, 12096, 12104, 12106',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$08:18 CST 2026-11-25 (Wall 12065, as relayed): "here is the problem i have... why are we looking at the transcripts?  to find technical errors or to figure out why the Oracle lost?  no one cares about the verdict?  who's trying to get the correct verdict??  THIS IS THE PRIMARY OBJECTIVE OF EACH RUN:   TO DETERMINE WHY THE ORACLE IS LOSING ROUNDS.  SECOND OBJECTIVE:  BUGS". 08:33 CST (as relayed by the coordinator): "I also want a section in the AAR stating why the Oracle lost ... add this as a requirement in the AAR.   The "why" will become the primary objective for the next run." 08:43 CST, in W3's thread (cmsg_017ZQamDMHrS6fqMHnQDVo58EiVLK14Rz22NxdMfga6Pvh), on the draft 2 card: "where is the second objective i mentioned". W3 withdrew that card (cmsg_017ZQamDMHrS6fqMHnQDVo588chB7c7JeP6SBDzhoMN76J) unwritten. Then W3's second card (cmsg_017ZQamDMHrS6fqMHnQDVo58PuTNkCW8MoPJyyhYvYtabf, "Write the two objectives (why the Oracle lost, then bugs) into the AAR rules now?"): he pressed "Write it" at 08:52 CST 2026-11-25.$t$::text),
  $j${"answer": "Write it", "question": "Write the two objectives (why the Oracle lost, then bugs) into the AAR rules now?", "options": ["Write it", "Change the wording"], "thread": "W3", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58PuTNkCW8MoPJyyhYvYtabf", "press_time": "08:52 CST 2026-11-25", "exact_text_message": "cmsg_017ZQamDMHrS6fqMHnQDVo58VtBD4ST6nxGxKv4hmAou6t", "withdrawn_card": "cmsg_017ZQamDMHrS6fqMHnQDVo588chB7c7JeP6SBDzhoMN76J (draft 2; withdrawn by W3 at 08:43 CST, never pressed)", "source": "W3's own cards and the press delivered to W3's thread."}$j$::jsonb,
  'W3',
  $j${"md5": "1e32a9630c360692fd198bc4510a175e", "path": "ask650/w3/wm_pairs_650_draft3.json", "note": "no separate plan file: the one pair is the plan and the change. Drafts 1 and 2: 792e9107 and dc8cd913 (first eight characters, as posted on the Wall).", "source": "md5sum by W3"}$j$::jsonb,
  $j$[{"path": "ask650/w3/wm_pairs_650_draft3.json", "md5": "1e32a9630c360692fd198bc4510a175e", "what": "the old and new text written (NOT IN GIT at the time of this draft: W3's commit is owed)"}]$j$::jsonb,
  $j${"wall_manual": "the_wall_manual is versioned and rows are immutable; version 20 stands unchanged as its own row. Undo is a version 22 holding the version 20 text, on the operator's word.", "engine": "not written; nothing to revert", "rehearsed": "the replacement was previewed on version 20 by W3 and reproduced by W1 (Wall 12096) before the card", "source": "W3's write call; Wall 12096"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (pair draft 1)", "wall_id": 12080, "md5_graded": "792e9107", "verdict_norm": "PASS", "source": "Wall 12080"}, {"seat": "W1", "verdict": "PASS (pair draft 2; card withdrawn, never written)", "wall_id": 12085, "md5_graded": "dc8cd913", "verdict_norm": "PASS", "source": "Wall 12085"}, {"seat": "W1", "verdict": "PASS (pair draft 3, file 1e32a963; W1 applied it to version 20 and got this product md5)", "wall_id": 12096, "md5_graded": "370fff76f0e2c05cf19e27bbb6feb452", "verdict_norm": "PASS", "source": "Wall 12096 (product md5 posted there as 370fff76; in full on W1's readback, Wall 12106)"}]$j$::jsonb,
  ARRAY['370fff76f0e2c05cf19e27bbb6feb452'], '[42271]'::jsonb,
  $j$[{"kind": "table row", "name": "the_wall_manual, section 7.4", "before": "version 20, md5 3fddfa284698997506798a0d4142ab18, 12,507 characters", "after": "version 21, md5 370fff76f0e2c05cf19e27bbb6feb452, 13,678 characters (+1,171); the_wall_manual_log row 18"}]$j$::jsonb,
  $j$[{"name": "Preview of the replacement on version 20", "result": "old text found once; result 13,678 characters, md5 370fff76; reproduced by W1", "source": "Wall 12096"}, {"name": "Checks inside the write call", "result": "pair md5, base version 20 md5, old text found once, result md5 and length, no launch since odv1_launches id 104: all passed, or the call would have raised", "source": "W3's write call"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "W1 readback PASS (Wall 12106): version 21 is the latest version, 13,678 characters, md5 370fff76f0e2c05cf19e27bbb6feb452, and in SQL it equals version 20 with the graded draft 3 pair applied. W1 did not check log row 18 or audit 42271.", "wall_id": 12106, "source": "Wall 12106"}]$j$::jsonb,
  $j${"case": "NO RUN SINCE THE WRITE.", "runs": [], "mark_for_the_next_run": "the next run's AAR carries, directly after its RUN line, the part WHY THE ORACLE LOST (each lost round or link with the judges' lines, the round text and the cause; or NONE LOST; or NO VERDICT with NOT COUNTED) and the part BUGS (or NONE FOUND), and states for each cause carried from run 42528 whether it recurred.", "not_shown": "an AAR drafted under the written rule; a next-run report stating whether a carried cause recurred.", "source": "the_wall_manual version 21, section 7.4"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "none", "wall_manual": "WRITTEN: version 21, md5 370fff76f0e2c05cf19e27bbb6feb452, 13,678 characters, log row 18, audit 42271 (this row's own change)."}$j$::jsonb,
  'read back', $j$[12065, 12080, 12083, 12085, 12093, 12096, 12104, 12106]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W3'], $j$[{"seat": "W3", "what": "drafted the pair and wrote the_wall_manual version 21 on the operator's card", "wall_id": 12104}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
